 slug: "pm-functional-location", module: "PM", track: "אחזקת מפעל · PM", course: "אובייקטים טכניים", chapter: "אובייקטים טכניים", index: 4,
 title: "מיקומים פונקציונליים", level: "בסיסי", minutes: 12, trust: "verified-docs", source: "SAP Help Portal — Plant Maintenance (S/4HANA)", lastReviewed: "2026-07-16",
